fix_code:
public Object solve(){
  int N = in.it();
  int[][] E = in.idx(N -1,2);
  long[] C = in.lg(N);
  ReRootingDp<Long, long[], Long> dp = new ReRootingDp<>(N){
    @Override
    protected long[] e(){ return new long[]{0, 0}; }

    @Override
    protected long[] agg(long[] a,long[] b){ return new long[]{a[0] + b[0], a[1] + b[1]}; }

    @Override
    protected long[] adj(long[] v,Edge<Long> e){ return new long[]{v[0] + C[e.v], v[1] + C[e.v] + v[0]}; }

    @Override
    protected Long ans(int u,long[] sum){
      long ret = 0;
      for (var d:sur(u))
        ret += d[1];
      return ret;
    }
  };
  for (var e:E)
    dp.addEdge(e[0],e[1]);

  long ans = Long.MAX_VALUE; // Initialize to the maximum possible value for comparison
  Long[] calc = dp.calc();
  for (int i = 0;i < N;i++)
    ans = min(ans,calc[i]);

  return ans;
}
